cat << 'LATEXEOF' > /app/poster/main.tex
\documentclass{article}
% A0 portrait: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── IMF Institutional Color Theme ──
\definecolor{primary}{HTML}{002244}       % IMF deep navy
\definecolor{secondary}{HTML}{1A4A7A}     % medium blue
\definecolor{accent}{HTML}{D4820C}        % burnt orange/amber for risk/warning
\definecolor{bgposter}{HTML}{EDF1F5}      % soft blue-gray poster background
\definecolor{redbg}{HTML}{FFF7F0}         % warm tint for risk cards
\definecolor{bluebg}{HTML}{EFF4FA}        % cool blue tint for data cards
\definecolor{darkbg}{HTML}{F0F3F7}        % neutral tint for policy cards
\definecolor{redtitlebg}{HTML}{FDECD8}    % amber title bar tint
\definecolor{bluetitlebg}{HTML}{DDE8F4}   % blue title bar tint
\definecolor{darktitlebg}{HTML}{DCE2EA}   % slate title bar tint
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E8F0FE}
\definecolor{statamber}{HTML}{FEF3E2}
\definecolor{accentlight}{HTML}{FFF3E0}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Subheader command ──
\newcommand{\subheader}[1]{%
  {\fontsize{36}{44}\selectfont\bfseries\color{primary}#1}\par\vspace{4pt}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=redtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════════════
% TITLE BAR (rows 1-3)
% ══════════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{78}{94}\selectfont\bfseries Global Economy in the Shadow of War}\\[14pt]
  {\fontsize{48}{58}\selectfont IMF World Economic Outlook Trends, 2024--2026}\\[16pt]
  {\fontsize{34}{42}\selectfont\color{white!80} IMF-World Bank Annual Meetings Research Symposium\quad$\vert$\quad Synthesis of 8 WEO Editions (Jul 2024--Apr 2026)}
}

% ══════════════════════════════════════════════════════════════════
% STAT BANNER (rows 4-6)
% ══════════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.85\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} 3.0--3.3\%}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} Global Growth Band\\(8 editions)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!40}{statamber}{\parbox{0.85\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{accent} 8/8}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} Editions: Risks\\Tilted Downside}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.85\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} $\sim$3.8\%}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} Pre-Pandemic Avg.\\(Benchmark)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \fcolorbox{accent!40}{statamber}{\parbox{0.85\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{accent} 2026}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textdark} Renewed Inflation\\Pressure Emerges}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════════════
% COLUMN 1: Growth Trajectory + Policy Evolution + References
% ══════════════════════════════════════════════════════════════════

% ── Growth Projections Table (Col 1, rows 6-12) ──
\posterbox[bluecard, title={Global Growth Projections Timeline}
]{name=growth, column=1, between=row6 and row12}{
  \fontsize{34}{44}\selectfont
  \vspace{4pt}
  {\fontsize{30}{38}\selectfont
  \renewcommand{\arraystretch}{1.55}
  \begin{tabular}{p{5.2cm} p{2.0cm} p{2.0cm} p{2.0cm}}
    \rowcolor{primary!18}
    \textbf{\color{primary}WEO Edition} & \textbf{\color{primary}'25} & \textbf{\color{primary}'26} & \textbf{\color{primary}'27} \\
    Jul 2024 ``Sticky Spot'' & 3.3\% & --- & --- \\
    \rowcolor{primary!8}
    Oct 2024 ``Policy Pivot'' & 3.3\% & --- & --- \\
    Jan 2025 ``Divergent'' & 3.3\% & 3.3\% & --- \\
    \rowcolor{primary!8}
    Apr 2025 ``Critical Juncture'' & \color{accent}$\downarrow$ & \color{accent}$\downarrow$ & --- \\
    Jul 2025 ``Tenuous'' & 3.0\% & 3.1\% & --- \\
    \rowcolor{primary!8}
    Oct 2025 ``Flux'' & \color{accent}$\downarrow$ & \color{accent}$\downarrow$ & --- \\
    Jan 2026 ``Steady'' & 3.3\% & 3.2\% & 3.2\% \\
    \rowcolor{primary!8}
    Apr 2026 ``Shadow of War'' & \color{accent}$\downarrow$ & \color{accent}$\downarrow$ & --- \\
  \end{tabular}
  }
  \vspace{6pt}

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont
  \color{accent!80!black}\textbf{Key:} $\downarrow$ = downward revision from prior edition. Growth stuck 0.5--0.8pp below pre-pandemic average.}}
}

% ── Policy Evolution (Col 1, rows 12-17) ──
\posterbox[darkcard, title={Evolving Policy Priorities}
]{name=policy, column=1, between=row12 and row17}{
  \fontsize{32}{42}\selectfont
  \vspace{2pt}

  \colorbox{primary!20}{\parbox{0.94\linewidth}{\fontsize{30}{38}\selectfont
  \textbf{Mid-2024:} Manage disinflation $\to$ begin careful monetary easing}}
  \vspace{6pt}

  \colorbox{secondary!18}{\parbox{0.94\linewidth}{\fontsize{30}{38}\selectfont
  \textbf{Late 2024:} Pivot monetary policy $\to$ ensure fiscal sustainability}}
  \vspace{6pt}

  \colorbox{primary!20}{\parbox{0.94\linewidth}{\fontsize{30}{38}\selectfont
  \textbf{Early 2025:} Rebuild fiscal buffers $\to$ address demographic gaps}}
  \vspace{6pt}

  \colorbox{secondary!18}{\parbox{0.94\linewidth}{\fontsize{30}{38}\selectfont
  \textbf{Mid-2025:} Restore confidence amid tariff uncertainty}}
  \vspace{6pt}

  \colorbox{primary!20}{\parbox{0.94\linewidth}{\fontsize{30}{38}\selectfont
  \textbf{Late 2025:} Strengthen frameworks $\to$ cautious industrial policy}}
  \vspace{6pt}

  \colorbox{accent!22}{\parbox{0.94\linewidth}{\fontsize{30}{38}\selectfont
  \textbf{\color{accent!80!black}2026:} Agile policy $\to$ defense-spending trade-offs $\to$ recovery}}
}

% ── References (Col 1, rows 17-20) ──
\posterbox[redcard, title={Sources}
]{name=refs, column=1, between=row17 and bottom}{
  \fontsize{30}{40}\selectfont

  \begin{enumerate}[label={\color{accent}\bfseries[\arabic*]}, itemsep=4pt, leftmargin=28pt]
    \item IMF (Jul 2024). WEO Update: \textit{Sticky Spot}
    \item IMF (Oct 2024). WEO: \textit{Policy Pivot, Rising Threats}
    \item IMF (Jan 2025). WEO Update: \textit{Divergent and Uncertain}
    \item IMF (Apr 2025). WEO: \textit{A Critical Juncture}
    \item IMF (Jul 2025). WEO Update: \textit{Tenuous Resilience}
    \item IMF (Oct 2025). WEO: \textit{Flux, Prospects Dim}
    \item IMF (Jan 2026). WEO Update: \textit{Steady amid Divergent Forces}
    \item IMF (Apr 2026). WEO: \textit{Shadow of War}
  \end{enumerate}
}

% ══════════════════════════════════════════════════════════════════
% COLUMN 2: Risk Assessment + Inflation + Special Themes
% ══════════════════════════════════════════════════════════════════

% ── Dominant Downside Risks (Col 2, rows 6-12) ──
\posterbox[redcard, title={Dominant Downside Risks}
]{name=risks, column=2, between=row6 and row12}{
  \fontsize{34}{44}\selectfont

  \colorbox{accent!22}{\parbox{0.94\linewidth}{\centering\fontsize{36}{44}\selectfont
  \textbf{\color{accent!80!black}``Balance of risks: tilted to the downside''}\\[2pt]
  \fontsize{28}{36}\selectfont\color{textgray}--- Consistent finding across all 8 editions}}
  \vspace{10pt}

  \begin{itemize}[label={\color{accent}$\blacktriangleright$}, itemsep=10pt]
    \item \textbf{Trade policy escalation}\\
      {\fontsize{30}{38}\selectfont Tariffs \& retaliatory measures; front-loading masks damage}
    \item \textbf{Geopolitical tensions}\\
      {\fontsize{30}{38}\selectfont Middle East conflicts, security concerns, war (Apr 2026)}
    \item \textbf{Technology re-evaluation}\\
      {\fontsize{30}{38}\selectfont AI/tech investment expectations face correction risk}
    \item \textbf{Persistent services inflation}\\
      {\fontsize{30}{38}\selectfont US return to target slower than peer economies}
  \end{itemize}
}

% ── Inflation Dynamics (Col 2, rows 12-17) ──
\posterbox[bluecard, title={Inflation Outlook \& Monetary Policy}
]{name=inflation, column=2, between=row12 and row17}{
  \fontsize{34}{44}\selectfont
  \vspace{2pt}

  \colorbox{secondary!20}{\parbox{0.94\linewidth}{\fontsize{32}{40}\selectfont
  \textbf{Global trend:} Headline inflation declining through 2026}}
  \vspace{8pt}

  \begin{itemize}[itemsep=8pt]
    \item Oct 2024 ``Policy Pivot'' $\to$ central banks begin easing
    \item US inflation: above target longer than peers
    \item Services inflation particularly sticky
    \item \textbf{\color{accent}Apr 2026:} Renewed pressure from defense spending \& supply disruptions
  \end{itemize}
  \vspace{6pt}

  \colorbox{accent!20}{\parbox{0.94\linewidth}{\fontsize{30}{38}\selectfont
  \color{accent!80!black}\textbf{Tension:} Disinflation progress is real but uneven, and new pressures threaten to reverse gains.}}
}

% ── Special Themes (Col 2, rows 17-20) ──
\posterbox[darkcard, title={Special Analytical Themes}
]{name=themes, column=2, between=row17 and bottom}{
  \fontsize{32}{42}\selectfont

  \begin{itemize}[itemsep=8pt]
    \item Role of monetary policy in global disinflation
    \item Social acceptability of structural reforms
    \item Fiscal cost \& effectiveness of industrial policy
    \item Aging populations \& gender disparities
    \item Migrant skill alignment \& labor markets
  \end{itemize}
  \vspace{4pt}
  {\fontsize{28}{36}\selectfont\color{textgray}\textit{Reflects IMF's broadening lens toward inclusive \& sustainable growth.}}
}

% ══════════════════════════════════════════════════════════════════
% COLUMN 3: Central Narrative + Growth Chart + Key Takeaways
% ══════════════════════════════════════════════════════════════════

% ── Central Narrative (Col 3, rows 6-10) ──
\posterbox[darkcard, title={The Story: Persistent Mediocrity}
]{name=narrative, column=3, between=row6 and row10}{
  \fontsize{34}{44}\selectfont

  \colorbox{primary!20}{\parbox{0.94\linewidth}{\fontsize{34}{44}\selectfont
  Global growth is neither collapsing nor recovering. The world economy is stuck in a narrow band---and the risks keep growing.}}
  \vspace{10pt}

  \begin{itemize}[itemsep=8pt]
    \item \textbf{8 editions, same story:} 3.0--3.3\% growth
    \item \textbf{Below potential:} 0.5--0.8pp under pre-pandemic trend
    \item \textbf{Downside dominates:} Every edition flags growing fragility
  \end{itemize}
}

% ── Growth Band Visualization (Col 3, rows 10-15) ──
\posterbox[bluecard, title={Growth Trajectory: The 3\% Trap}
]{name=chart, column=3, between=row10 and row15}{
  \fontsize{34}{44}\selectfont
  \vspace{2pt}
  \centering

  \begin{tikzpicture}[x=2.8cm, y=5.5cm, font=\fontsize{26}{32}\selectfont]
    % Background bands
    \fill[primary!8] (0,2.85) rectangle (7.5,3.45);
    \draw[primary!30, dashed, thick] (0,3.8) -- (7.5,3.8) node[right, font=\fontsize{24}{30}\selectfont] {Pre-pandemic avg: 3.8\%};
    \draw[accent!40, thick] (0,3.0) -- (7.5,3.0);
    \draw[accent!40, thick] (0,3.3) -- (7.5,3.3);
    \node[font=\fontsize{22}{28}\selectfont, color=accent!70!black, rotate=90] at (-0.6,3.15) {WEO band};

    % Axes
    \draw[thick, primary!60] (0,2.5) -- (0,4.0);
    \draw[thick, primary!60] (0,2.5) -- (7.5,2.5);

    % Y-axis labels
    \foreach \y/\l in {2.5/2.5, 3.0/3.0, 3.3/3.3, 3.5/3.5, 3.8/3.8} {
      \draw[primary!40] (-0.1,\y) -- (0,\y);
      \node[left, font=\fontsize{24}{30}\selectfont] at (-0.15,\y) {\l\%};
    }

    % Data points (2025 forecasts across editions)
    \filldraw[secondary, thick] (0.5,3.3) circle (5pt) node[above=6pt, font=\fontsize{22}{28}\selectfont] {Jul '24};
    \filldraw[secondary, thick] (1.5,3.3) circle (5pt) node[above=6pt, font=\fontsize{22}{28}\selectfont] {Oct '24};
    \filldraw[secondary, thick] (2.5,3.3) circle (5pt) node[above=6pt, font=\fontsize{22}{28}\selectfont] {Jan '25};
    \filldraw[accent, thick] (3.5,3.15) circle (5pt) node[below=6pt, font=\fontsize{22}{28}\selectfont, color=accent] {Apr '25};
    \filldraw[secondary, thick] (4.5,3.0) circle (5pt) node[below=6pt, font=\fontsize{22}{28}\selectfont] {Jul '25};
    \filldraw[accent, thick] (5.5,2.9) circle (5pt) node[below=6pt, font=\fontsize{22}{28}\selectfont, color=accent] {Oct '25};
    \filldraw[secondary, thick] (6.5,3.3) circle (5pt) node[above=6pt, font=\fontsize{22}{28}\selectfont] {Jan '26};

    % Connect with line
    \draw[secondary, thick, opacity=0.7] (0.5,3.3) -- (1.5,3.3) -- (2.5,3.3) -- (3.5,3.15) -- (4.5,3.0) -- (5.5,2.9) -- (6.5,3.3);

    % Arrow for Apr 2026
    \draw[accent, ultra thick, ->] (6.5,3.3) -- (7.3,3.05);
    \node[font=\fontsize{22}{28}\selectfont\bfseries, color=accent, right] at (7.0,2.85) {Apr '26};
