\documentclass{article}
% A0 portrait: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── IMF Institutional Color Theme ──
\definecolor{primary}{HTML}{002244}       % IMF deep navy
\definecolor{secondary}{HTML}{1A4A7A}     % medium blue
\definecolor{accent}{HTML}{D4820C}        % burnt orange/amber for risk/warning
\definecolor{bgposter}{HTML}{EDF1F5}      % soft blue-gray poster background
\definecolor{redbg}{HTML}{FFF7F0}         % warm tint for risk cards
\definecolor{bluebg}{HTML}{EFF4FA}        % cool blue tint for data cards
\definecolor{darkbg}{HTML}{F0F3F7}        % neutral tint for policy cards
\definecolor{redtitlebg}{HTML}{FDECD8}    % amber title bar tint
\definecolor{bluetitlebg}{HTML}{DDE8F4}   % blue title bar tint
\definecolor{darktitlebg}{HTML}{DCE2EA}   % slate title bar tint
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{E8F0FE}
\definecolor{statamber}{HTML}{FEF3E2}
\definecolor{accentlight}{HTML}{FFF3E0}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Subheader command ──
\newcommand{\subheader}[1]{%
  {\fontsize{36}{44}\selectfont\bfseries\color{primary}#1}\par\vspace{4pt}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=redtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
