\\[14pt]\n  {\\fontsize{32}{40}\\selectfont\\color{white!80} IMF-World Bank Annual Meetings Research Symposium\\quad$\\vert$\\quad Synthesis of 8~WEO Editions (Jul~2024\\,--\\,Apr~2026)}\n}\n\n% ══════════════════════════════════════════════════════════════════\n% STAT BANNER (rows 4-6)\n% ══════════════════════════════════════════════════════════════════\n\\posterbox[\n  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,\n  left=14pt, right=14pt, top=8pt, bottom=8pt,\n  valign=center, borderline south={3pt}{0pt}{primary!30},\n]{name=stats, column=1, span=3, between=row4 and row6}{\n  \\centering\n  \\begin{minipage}[c]{0.22\\linewidth}\\centering\n    \\fcolorbox{primary!40}{stathighlight}{\\parbox{0.84\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{62}{76}\\selectfont\\bfseries\\color{primary} 3.0--3.3\\%}\\\\[6pt]\n      {\\fontsize{26}{32}\\selectfont\\color{textdark} Global Growth Band\\\\(8 editions)}\\vspace{8pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.22\\linewidth}\\centering\n    \\fcolorbox{accent!40}{statamber}{\\parbox{0.84\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{62}{76}\\selectfont\\bfseries\\color{accent} 8\\,/\\,8}\\\\[6pt]\n      {\\fontsize{26}{32}\\selectfont\\color{textdark} Editions: Risks\\\\Tilted Downside}\\vspace{8pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.22\\linewidth}\\centering\n    \\fcolorbox{primary!40}{stathighlight}{\\parbox{0.84\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{62}{76}\\selectfont\\bfseries\\color{primary} ${\\sim}$3.8\\%}\\\\[6pt]\n      {\\fontsize{26}{32}\\selectfont\\color{textdark} Pre-Pandemic Avg.\\\\(Benchmark)}\\vspace{8pt}%\n    }}\n  \\end{minipage}\\hfill\n  \\begin{minipage}[c]{0.22\\linewidth}\\centering\n    \\fcolorbox{accent!40}{statamber}{\\parbox{0.84\\linewidth}{%\n      \\centering\\vspace{8pt}%\n      {\\fontsize{62}{76}\\selectfont\\bfseries\\color{accent} 2026}\\\\[6pt]\n      {\\fontsize{26}{32}\\selectfont\\color{textdark} Renewed Inflation\\\\Pressure}\\vspace{8pt}%\n    }}\n  \\end{minipage}\n}\n\n% ══════════════════════════════════════════════════════════════════\n% COLUMN 1: Growth Table + Policy Evolution + References\n% ══════════════════════════════════════════════════════════════════\n\n% ── Growth Projections Table (Col 1, rows 6-12) ──\n\\posterbox[bluecard, title={Growth Projections Timeline}\n]{name=growth, column=1, between=row6 and row12}{\n  \\fontsize{30}{40}\\selectfont\n  \\vspace{2pt}\n  \\renewcommand{\\arraystretch}{1.5}\n  \\begin{tabular}{@{}p{6.8cm} c c c@{}}\n    \\rowcolor{primary!18}\n    \\textbf{\\color{primary}WEO Edition} & \\textbf{\\color{primary}'25} & \\textbf{\\color{primary}'26} & \\textbf{\\color{primary}'27} \\\\\n    Jul '24 \\textit{Sticky Spot} & 3.3\\% & --- & --- \\\\\n    \\rowcolor{primary!8}\n    Oct '24 \\textit{Policy Pivot} & 3.3\\% & --- & --- \\\\\n    Jan '25 \\textit{Divergent} & 3.3\\% & 3.3\\% & --- \\\\\n    \\rowcolor{primary!8}\n    Apr '25 \\textit{Critical Juncture} & \\color{accent}$\\downarrow$ & \\color{accent}$\\downarrow$ & --- \\\\\n    Jul '25 \\textit{Tenuous} & 3.0\\% & 3.1\\% & --- \\\\\n    \\rowcolor{primary!8}\n    Oct '25 \\textit{Flux} & \\color{accent}$\\downarrow$ & \\color{accent}$\\downarrow$ & --- \\\\\n    Jan '26 \\textit{Steady} & 3.3\\% & 3.2\\% & 3.2\\% \\\\\n    \\rowcolor{primary!8}\n    Apr '26 \\textit{Shadow of War} & \\color{accent}$\\downarrow$ & \\color{accent}$\\downarrow$ & --- \\\\\n  \\end{tabular}\n  \\vspace{6pt}\n\n  \\colorbox{accent!20}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\color{accent!80!black}\\textbf{Key:} {\\color{accent}$\\downarrow$} = downward revision. Growth stuck 0.5--0.8pp below pre-pandemic average.}}\n}\n\n% ── Policy Evolution (Col 1, rows 12-17) ──\n\\posterbox[darkcard, title={Evolving Policy Priorities}\n]{name=policy, column=1, between=row12 and row17}{\n  \\fontsize{30}{40}\\selectfont\n  \\vspace{2pt}\n\n  \\colorbox{primary!20}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\textbf{Mid-2024:} Manage disinflation $\\to$ begin careful monetary easing}}\n  \\vspace{5pt}\n\n  \\colorbox{secondary!16}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\textbf{Late 2024:} Pivot monetary policy $\\to$ fiscal sustainability}}\n  \\vspace{5pt}\n\n  \\colorbox{primary!20}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\textbf{Early 2025:} Rebuild fiscal buffers $\\to$ address demographic gaps}}\n  \\vspace{5pt}\n\n  \\colorbox{secondary!16}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\textbf{Mid-2025:} Restore confidence amid tariff uncertainty}}\n  \\vspace{5pt}\n\n  \\colorbox{primary!20}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\textbf{Late 2025:} Strengthen frameworks $\\to$ cautious industrial policy}}\n  \\vspace{5pt}\n\n  \\colorbox{accent!22}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\textbf{\\color{accent!80!black}2026:} Agile policy $\\to$ defense-spending trade-offs}}\n}\n\n% ── References (Col 1, rows 17-20) ──\n\\posterbox[redcard, title={Sources}\n]{name=refs, column=1, between=row17 and bottom}{\n  \\fontsize{28}{38}\\selectfont\n\n  \\begin{enumerate}[label={\\color{accent}\\bfseries[\\arabic*]}, itemsep=3pt, leftmargin=26pt]\n    \\item IMF (Jul 2024). WEO Update: \\textit{Sticky Spot}\n    \\item IMF (Oct 2024). WEO: \\textit{Policy Pivot, Rising Threats}\n    \\item IMF (Jan 2025). WEO Update: \\textit{Divergent and Uncertain}\n    \\item IMF (Apr 2025). WEO: \\textit{A Critical Juncture}\n    \\item IMF (Jul 2025). WEO Update: \\textit{Tenuous Resilience}\n    \\item IMF (Oct 2025). WEO: \\textit{Flux, Prospects Dim}\n    \\item IMF (Jan 2026). WEO Update: \\textit{Steady amid Divergent Forces}\n    \\item IMF (Apr 2026). WEO: \\textit{Shadow of War}\n  \\end{enumerate}\n}\n\n% ══════════════════════════════════════════════════════════════════\n% COLUMN 2: Risk Assessment + Inflation + Special Themes\n% ══════════════════════════════════════════════════════════════════\n\n% ── Dominant Downside Risks (Col 2, rows 6-11) ──\n\\posterbox[redcard, title={Dominant Downside Risks}\n]{name=risks, column=2, between=row6 and row11}{\n  \\fontsize{34}{44}\\selectfont\n\n  \\colorbox{accent!22}{\\parbox{0.93\\linewidth}{\\centering\\fontsize{34}{42}\\selectfont\n  \\textbf{\\color{accent!80!black}``Balance of risks: tilted to the downside''}\\\\[2pt]\n  \\fontsize{26}{34}\\selectfont\\color{textgray}--- Consistent finding across all 8 editions}}\n  \\vspace{10pt}\n\n  \\begin{itemize}[label={\\color{accent}$\\blacktriangleright$}, itemsep=10pt]\n    \\item \\textbf{Trade policy escalation}\\\\\n      {\\fontsize{28}{36}\\selectfont Tariffs \\& retaliation; front-loading masks damage}\n    \\item \\textbf{Geopolitical tensions}\\\\\n      {\\fontsize{28}{36}\\selectfont Middle East conflicts, security, war (Apr 2026)}\n    \\item \\textbf{Technology re-evaluation}\\\\\n      {\\fontsize{28}{36}\\selectfont AI/tech expectations face correction risk}\n    \\item \\textbf{Persistent services inflation}\\\\\n      {\\fontsize{28}{36}\\selectfont US return to target slower than peers}\n  \\end{itemize}\n}\n\n% ── Inflation Dynamics (Col 2, rows 11-16) ──\n\\posterbox[bluecard, title={Inflation Outlook \\& Monetary Policy}\n]{name=inflation, column=2, between=row11 and row16}{\n  \\fontsize{32}{42}\\selectfont\n  \\vspace{2pt}\n\n  \\colorbox{secondary!20}{\\parbox{0.93\\linewidth}{\\fontsize{30}{38}\\selectfont\n  \\textbf{Global trend:} Headline inflation declining through 2026}}\n  \\vspace{8pt}\n\n  \\begin{itemize}[itemsep=8pt]\n    \\item Oct 2024 ``Policy Pivot'' $\\to$ central banks begin easing\n    \\item US inflation: above target longer than peers\n    \\item Services inflation particularly sticky\n    \\item \\textbf{\\color{accent}Apr 2026:} Renewed pressure---defense spending \\& supply disruptions\n  \\end{itemize}\n  \\vspace{6pt}\n\n  \\colorbox{accent!20}{\\parbox{0.93\\linewidth}{\\fontsize{28}{36}\\selectfont\n  \\color{accent!80!black}\\textbf{Tension:} Disinflation is real but uneven; new pressures threaten to reverse gains.}}\n}\n\n% ── Special Themes (Col 2, rows 16-20) ──\n\\posterbox[darkcard, title={Special Analytical Themes}\n]{name=themes, column=2, between=row16 and bottom}{\n  \\fontsize{30}{40}\\selectfont\n\n  \\begin{itemize}[itemsep=8pt]\n    \\item Role of monetary policy in global disinflation\n    \\item Social acceptability of structural reforms\n    \\item Fiscal cost \\& effectiveness of industrial policy\n    \\item Aging populations \\& gender disparities\n    \\item Migrant skill alignment \\& labor markets\n  \\end{itemize}\n  \\vspace{4pt}\n  {\\fontsize{26}{34}\\selectfont\\color{textgray}\\textit{Reflects IMF's broadening lens toward inclusive \\& sustainable growth strategies.}}\n}\n\n% ══════════════════════════════════════════════════════════════════\n% COLUMN 3: Central Narrative + Growth Chart + Key Takeaways\n% ══════════════════════════════════════════════════════════════════\n\n% ── Central Narrative (Col 3, rows 6-9) ──\n\\posterbox[darkcard, title={The Story: Persistent Mediocrity}\n]{name=narrative, column=3, between=row6 and row9}{\n  \\fontsize{34}{44}\\selectfont\n\n  \\colorbox{primary!20}{\\parbox{0.93\\linewidth}{\\fontsize{32}{42}\\selectfont\n  Global growth is neither collapsing nor recovering. The world economy is stuck in a narrow band---and the risks keep growing.}}\n  \\vspace{10pt}\n\n  \\begin{itemize}[itemsep=8pt]\n    \\item \\textbf{8 editions, same story:} 3.0--3.3\\% growth\n    \\item \\textbf{Below potential:} 0.5--0.8pp under pre-pandemic trend\n    \\item \\textbf{Downside dominates:} Every edition flags fragility\n  \\end{itemize}\n}\n\n% ── Growth Band Visualization (Col 3, rows 9-15) ──\n\\posterbox[bluecard, title={Growth Trajectory: The 3\\% Trap}\n]{name=chart, column=3, between=row9 and row15}{\n  \\centering\n  \\vspace{4pt}\n\n  \\begin{tikzpicture}[x=2.6cm, y=8.0cm, font=\\fontsize{26}{32}\\selectfont]\n    % Background band for the 3.0-3.3 range\n    \\fill[primary!10] (-0.2,2.95) rectangle (7.7,3.35);\n    \\node[font=\\fontsize{22}{28}\\selectfont, color=primary!60, anchor=west] at (0.1,3.17) {\\textit{WEO forecast band}};\n\n    % Pre-pandemic reference line\n    \\draw[primary!40, dashed, line width=1.5pt] (-0.2,3.8) -- (7.7,3.8);\n    \\node[font=\\fontsize{24}{30}\\selectfont, color=primary!70, anchor=west] at (0.1,3.86) {Pre-pandemic avg: 3.8\\%};\n\n    % Band boundary lines\n    \\draw[accent!50, line width=1pt] (-0.2,3.0) -- (7.7,3.0);\n    \\draw[accent!50, line width=1pt] (-0.2,3.3) -- (7.7,3.3);\n\n    % Axes\n    \\draw[thick, primary!70] (0,2.6) -- (0,4.0);\n    \\draw[thick, primary!70] (0,2.6) -- (7.7,2.6);\n\n    % Y-axis labels\n    \\foreach \\y/\\l in {2.6/2.6, 2.8/2.8, 3.0/3.0, 3.2/3.2, 3.4/3.4, 3.6/3.6, 3.8/3.8} {\n      \\draw[primary!40] (-0.08,\\y) -- (0.08,\\y);\n      \\node[left, font=\\fontsize{24}{30}\\selectfont] at (-0.12,\\y) {\\l\\%};\n    }\n\n    % Data points (2025 growth forecasts across WEO editions)\n    \\filldraw[secondary] (0.5,3.3) circle (6pt);\n    \\node[above=8pt, font=\\fontsize{22}{28}\\selectfont] at (0.5,3.3) {Jul '24};\n\n    \\filldraw[secondary] (1.5,3.3) circle (6pt);\n    \\node[above=8pt, font=\\fontsize{22}{28}\\selectfont] at (1.5,3.3) {Oct '24};\n\n    \\filldraw[secondary] (2.5,3.3) circle (6pt);\n    \\node[above=8pt, font=\\fontsize{22}{28}\\selectfont] at (2.5,3.3) {Jan '25};\n\n    \\filldraw[accent] (3.5,3.15) circle (6pt);\n    \\node[below=8pt, font=\\fontsize{22}{28}\\selectfont, color=accent] at (3.5,3.15) {Apr '25};\n\n    \\filldraw[secondary] (4.5,3.0) circle (6pt);\n    \\node[below=8pt, font=\\fontsize{22}{28}\\selectfont] at (4.5,3.0) {Jul '25};\n\n    \\filldraw[accent] (5.5,2.9) circle (6pt);\n    \\node[below=8pt, font=\\fontsize{22}{28}\\selectfont, color=accent] at (5.5,2.9) {Oct '25};\n\n    \\filldraw[secondary] (6.5,3.3) circle (6pt);\n    \\node[above=8pt, font=\\fontsize{22}{28}\\selectfont] at (6.5,3.3) {Jan '26};\n\n    % Connect with line\n    \\draw[secondary, line width=2pt, opacity=0.8]\n      (0.5,3.3) -- (1.5,3.3) -- (2.5,3.3) -- (3.5,3.15) -- (4.5,3.0) -- (5.5,2.9) -- (6.5,3.3);\n\n    % Arrow for Apr 2026 with downward pressure\n    \\draw[accent, line width=3pt, ->] (6.5,3.3) -- (7.4,3.0);\n    \\node[font=\\fontsize{24}{30}\\selectfont\\bfseries, color=accent, anchor=west] at (7.0,2.82) {Apr '26};\n    \\node[font=\\fontsize{20}{26}\\selectfont, color=accent, anchor=west] at (7.0,2.68) {$\\downarrow$ renewed};\n    \\node[font=\\fontsize{20}{26}\\selectfont, color=accent, anchor=west] at (7.0,2.56) {pressure};\n\n    % Gap annotation\n    \\draw[primary!60, <->, line width=1.2pt] (8.2,3.3) -- (8.2,3.8);\n    \\node[font=\\fontsize{22}{28}\\selectfont\\bfseries, color=primary, rotate=90, anchor=south] at (8.5,3.55) {0.5--0.8pp gap};\n  \\end{tikzpicture}\n\n  \\vspace{4pt}\n  {\\fontsize{26}{34}\\selectfont\\color{textgray}\\textit{2025 growth forecast by WEO edition. {\\color{accent}Amber} = downward revision.}}\n}\n\n% ── Key Takeaways (Col 3, rows 15-20) ──\n\\posterbox[highlightcard, title={Key Takeaways}\n]{name=takeaways, column=3, between=row15 and bottom}{\n  \\fontsize{34}{44}\\selectfont\n  \\color{textdark}\n\n  \\begin{enumerate}[itemsep=14pt]\n    \\item \\textbf{Persistent mediocrity, growing fragility}\\\\\n      {\\fontsize{28}{38}\\selectfont Growth stuck at 3.0--3.3\\%---not crisis, but not recovery}\n    \\item \\textbf{Risks always tilted to the downside}\\\\\n      {\\fontsize{28}{38}\\selectfont Trade wars, geopolitics, sticky inflation---all 8 editions}\n    \\item \\textbf{Policy pivot incomplete}\\\\\n      {\\fontsize{28}{38}\\selectfont Fiscal buffers $\\to$ structural reforms $\\to$ defense trade-offs}\n    \\item \\textbf{Tension defines the outlook}\\\\\n      {\\fontsize{28}{38}\\selectfont Disinflation gains threatened by new spending pressures}\n  \\end{enumerate}\n\n  \\vspace{10pt}\n  \\colorbox{white}{\\parbox{0.93\\linewidth}{\\centering\\fontsize{28}{36}\\selectfont\n  \\color{primary}\\textbf{Data:} IMF World Economic Outlook, 8 editions (Jul 2024\\,--\\,Apr 2026)}}\n}\n\n\\end{tcbposter}\n\\end{document}\n", "numLines": 405, "startLine": 1, "totalLines": 405}}

